// Data loading + small helpers shared by the dashboard.
// All files come from public/data, generated by scripts/build_data.py.

const base = (import.meta.env?.BASE_URL ?? '/') + 'data/'   // env is undefined outside Vite (check scripts)
const cache = new Map()

export function loadJSON(path) {
  if (!cache.has(path)) {
    cache.set(path, fetch(base + path).then((r) => {
      if (!r.ok) throw new Error(`Could not load ${path} (${r.status}). Run "npm run data" first.`)
      return r.json()
    }))
  }
  return cache.get(path)
}

export const loadCore = () =>
  Promise.all(['meta.json', 'metrics.json', 'daily.json', 'alerts.json', 'building.json'].map(loadJSON))
    .then(([meta, metrics, daily, alerts, building]) => ({ meta, metrics, daily, alerts, building }))

export const loadSeries = (zoneId) => loadJSON(`series/${zoneId}.json`)

// ---------- formatting
export const zoneLabel = (id) => id.replace('F', 'Floor ').replace('_Z', ' · Zone ')
export const shortZone = (id) => id.replace('_', ' ')
export const fmt = (v, nd = 1) => (v == null || Number.isNaN(v) ? '–' : v.toFixed(nd))
export const pct = (v, nd = 1) => (v == null ? '–' : `${v.toFixed(nd)}%`)
export const hh = (h) => `${String(h).padStart(2, '0')}:00`
export const hhmm = (mins) => {
  const h = Math.floor(mins / 60), m = mins % 60
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`
}

const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
export const parseDate = (s) => new Date(s + 'T00:00:00')
export const dow = (s) => DOW[parseDate(s).getDay()]
export const dayMonth = (s) => parseDate(s).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })

export function addDays(s, n) {
  const d = parseDate(s)
  d.setDate(d.getDate() + n)
  const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, '0'), dd = String(d.getDate()).padStart(2, '0')
  return `${y}-${m}-${dd}`
}

// ASHRAE Guideline 14, hourly calibration: CV(RMSE) <= 30 %, |NMBE| <= 10 %
export const ASHRAE = { cvrmse: 30, nmbe: 10 }
export const passesAshrae = (m) => m && m.CVRMSE != null && m.CVRMSE <= ASHRAE.cvrmse && Math.abs(m.NMBE) <= ASHRAE.nmbe

// Short display names for the model columns
export const modelName = (id) => ({
  'B1 seasonal naive': 'B1 · Seasonal naive',
  'B2 average profile': 'B2 · Average profile',
  'B3 calendar + AC lags': 'B3 · Calendar + lags',
  'LGBM final': 'LightGBM (final)',
  'LGBM full': 'LightGBM (all features)',
  'XGB accuracy-first': 'XGBoost (accuracy-first)',
  'XGB research-preserving': 'XGBoost (research-preserving)',
}[id] ?? id)
